import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Quick Start — Glacier Pack","description":"Get the Glacier Pack hub plus three starter addons — Recycle Bin, URL Download and Site Alerts — running on your panel, and make your first save through the hub.","frontmatter":{"title":"Quick Start — Glacier Pack","description":"Get the Glacier Pack hub plus three starter addons — Recycle Bin, URL Download and Site Alerts — running on your panel, and make your first save through the hub.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/getting-started/quick-start.md","filePath":"glacier-pack/getting-started/quick-start.md","lastUpdated":1785522036000}'),n={name:"glacier-pack/getting-started/quick-start.md"};function r(l,a,o,h,d,c){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>The fastest useful Glacier Pack setup: the <strong>hub</strong> plus three starter addons — <strong>Recycle Bin</strong> (recoverable deletes), <strong>URL Download</strong> (fetch files straight into a server), and <strong>Site Alerts</strong> (announcement banners). Everything is managed from one page afterwards.</p><hr><h2 id="_1-install-the-hub" tabindex="-1">1. Install the hub <a class="header-anchor" href="#_1-install-the-hub" aria-label="Permalink to &quot;1. Install the hub&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><p>This registers the hub provider, adds the <strong>Glacier Pack</strong> sidebar tab, and clears caches. Open <strong>Admin → Glacier Pack</strong> — the rail lists all 24 addons; the three you are about to install will light up as they land.</p><hr><h2 id="_2-install-the-starter-addons" tabindex="-1">2. Install the starter addons <a class="header-anchor" href="#_2-install-the-starter-addons" aria-label="Permalink to &quot;2. Install the starter addons&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../recycle-bin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../url-download</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../site-alerts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/install.sh</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Recycle Bin patches the panel&#39;s React frontend — run a rebuild after installing it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:production</span></span></code></pre></div><p>URL Download and Site Alerts need no build step.</p></div><hr><h2 id="_3-your-first-save-through-the-hub" tabindex="-1">3. Your first save through the hub <a class="header-anchor" href="#_3-your-first-save-through-the-hub" aria-label="Permalink to &quot;3. Your first save through the hub&quot;">​</a></h2><p>Open <strong>Admin → Glacier Pack</strong> and click <strong>Recycle Bin</strong> in the rail (or go straight to <code>/admin/glacier-pack?a=recycle-bin</code>).</p><ol><li>Set <strong>Default retention window (hours)</strong> to how long trashed files should stay recoverable — the default is <code>24</code>.</li><li>Set <strong>Default per-server capacity</strong> — <code>0</code> means unlimited; trashed files count against the server&#39;s real disk quota, so a limit is worth setting on shared nodes.</li><li>Press <strong>Save settings</strong>.</li></ol><p>You land back on the same pane with the green <strong>Settings saved.</strong> banner — that round-trip is how every addon in the family saves.</p><hr><h2 id="_4-try-the-other-two" tabindex="-1">4. Try the other two <a class="header-anchor" href="#_4-try-the-other-two" aria-label="Permalink to &quot;4. Try the other two&quot;">​</a></h2><p><strong>URL Download</strong> (<code>?a=url-download</code>) — set <strong>Max file size</strong> (default <code>10 GB</code>) and <strong>Max URLs per batch</strong> (default <code>3</code>), then save. Users get a <strong>Download from URL</strong> button in the server file manager immediately.</p><p><strong>Site Alerts</strong> (<code>?a=site-alerts</code>) — click the create form, pick a type (<code>info</code>, <code>success</code>, <code>warning</code>, <code>danger</code>), write a message (<code>**bold**</code>, <code>*italic*</code> and <code>[links](https://url)</code> supported), and save. The banner appears on every client page within seconds — users can dismiss it, and editing the alert re-shows it.</p><hr><h2 id="_5-see-it-as-a-user" tabindex="-1">5. See it as a user <a class="header-anchor" href="#_5-see-it-as-a-user" aria-label="Permalink to &quot;5. See it as a user&quot;">​</a></h2><ul><li><strong>Recycle Bin:</strong> open any server&#39;s file manager, delete a file, then use the <strong>Recycle Bin</strong> toolbar button to restore it.</li><li><strong>URL Download:</strong> in the same file manager, click <strong>Download from URL</strong>, paste a link, pick a folder, watch it land — no SFTP round-trip.</li><li><strong>Site Alerts:</strong> open the dashboard as any user; your banner sits above the app content.</li></ul><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong><a href="./../user-guide/addons">All 24 addons →</a></strong> — what each one does and where it lives.</li><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting on every pane.</li><li><strong><a href="./installation">Installation →</a></strong> — full prerequisites, verification and troubleshooting.</li></ul>`,25)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
